pub type Payment = enum {
  Cash,
  Card(provider: Str),
  Crypto(coin: Str),
}

fn Payment.fee(self: &Payment) -> Float64 {
  match self {
    Cash => { return 0.0; }
    Card(_) => { return 0.03; }
    Crypto(_) => { return 0.01; }
  }
}

fn Payment.description(self: &Payment) -> Str {
  match self {
    Cash => { return "Cash payment"; }
    Card(provider) => { return "Card: " + provider; }
    Crypto(coin) => { return "Crypto: " + coin; }
  }
}

fn main() -> Int {
  let p1 = Payment.Cash;
  let p2 = Payment.Card("Visa");
  let p3 = Payment.Crypto("BTC");
  let total = p1.fee() + p2.fee() + p3.fee();
  return (total * 100.0) as Int;
}
